  StoryDefinition(id: "glass-hour", title: "The Glass Hour", genre: "Fantasy", description: "A clockwork city steals one minute of your life every midnight.", art: "assets/art/academy.png", character: "Aira", tag: "TEMPORARY TEST STORY", foundation: "Alice’s Adventures in Wonderland", sourceUrl: "https://www.gutenberg.org/ebooks/11", opening: "The station clock strikes thirteen. Every passenger freezes except you. Aira opens a glass umbrella. “Someone has stolen tomorrow. We have one hour to find it.”", choices: ["Inspect the frozen clock", "Ask who stole tomorrow", "Enter the mirror station"], responses: ["Behind the clock face, you find a moving map. Aira points to a station that does not exist. “We need a ticket made from a memory.”", "“The keeper of lost minutes,” Aira says. “But he used to protect this city. We should learn what changed before we accuse him.”", "The mirror opens onto a platform floating above the clouds. Your reflection stays behind, waving a warning you cannot hear."]),
  StoryDefinition(id: "storm-couriers", title: "Storm Couriers", genre: "Adventure", description: "Deliver a living compass across a sky broken into islands.", art: "assets/art/lantern.png", character: "Mika", tag: "TEMPORARY TEST STORY", foundation: "The Wonderful Wizard of Oz", sourceUrl: "https://www.gutenberg.org/ebooks/55", opening: "A storm leaves your delivery glider stranded on a floating island. Mika catches a compass that points toward voices. “Our parcel is alive. And it wants to go home.”", choices: ["Listen to the compass", "Repair the glider", "Explore the wind bridge"], responses: ["The compass whispers three names. Mika recognizes one: the engineer who disappeared before the islands separated. Your delivery has become a rescue.", "You patch the sail while Mika gathers copper leaves. The glider lifts, but its shadow stays on the ground. Something here is holding you.", "Each step rings like a bell. Across the bridge, a silent village lights its windows in answer. Mika wonders whether the bridge is calling for help."]),
  StoryDefinition(id: "salt-crown", title: "The Salt Crown", genre: "Adventure", description: "A prisoner’s map leads to an island that remembers every betrayal.", art: "assets/art/lantern.png", character: "Ren", tag: "TEMPORARY TEST STORY", foundation: "The Count of Monte Cristo", sourceUrl: "https://www.gutenberg.org/ebooks/1184", opening: "Your ship reaches an island erased from every chart. Ren unfolds a map inherited from a vanished prisoner. “The treasure is evidence. Someone paid dearly to hide it.”", choices: ["Read the prisoner’s map", "Question the harbor keeper", "Enter the sealed archive"], responses: ["Salt reveals a second route on the paper. Ren follows its marks to a lighthouse whose beam points underground.", "The keeper recognizes the seal and locks the door. “If you reveal the truth, the council falls,” she says. Ren asks you whether justice can wait.", "Inside, you find letters addressed to people not yet born. The archive is preserving a crime before it happens."]),
  StoryDefinition(id: "ember-letter", title: "The Ember Letter", genre: "Fantasy", description: "An enchanted mark exposes lies, but the truth has a price.", art: "assets/art/academy.png", character: "Aira", tag: "TEMPORARY TEST STORY", foundation: "The Scarlet Letter", sourceUrl: "https://www.gutenberg.org/ebooks/33", opening: "At the academy tribunal, a glowing mark appears on your wrist. Aira steps between you and the judges. “It reveals a broken promise. It does not tell us whose.”", choices: ["Examine the glowing mark", "Challenge the tribunal", "Search the promise ledger"], responses: ["The mark warms near Aira’s old badge. She looks startled. “I promised to protect someone here. I cannot remember their name.”", "The judges offer a trial by memory. You may show one true moment, but everyone present will see it. Aira waits for your decision.", "The ledger contains a page torn from tomorrow. Your name is written beside an oath you have never made."]),
  StoryDefinition(id: "moon-tide", title: "Moon Tide Observatory", genre: "Sci-fi", description: "Follow a distress signal beneath an ocean that rises into space.", art: "assets/art/signals.png", character: "Ren", tag: "TEMPORARY TEST STORY", foundation: "Twenty Thousand Leagues under the Seas", sourceUrl: "https://www.gutenberg.org/ebooks/164", opening: "The ocean climbs into the night sky. Ren seals the observatory hatch as a distress signal arrives from below. “The sender is using our station code. This message is fifty years old.”", choices: ["Decode the distress signal", "Launch the diving capsule", "Inspect the lunar engine"], responses: ["The signal contains coordinates and a familiar voice. Ren compares the recording with yours. The match is impossible, but exact.", "Your capsule sinks through a field of luminous machines. One follows you, projecting a symbol that means welcome rather than danger.", "The engine is drawing water upward to shield the city. Shutting it down could save the station and expose everyone below. Ren asks for another way."])
